observation.command:
cd /workspace
# instrument install_profile_modules to dump the full module list with sort order
cat > /tmp/instrument.py <<'PYEOF'
import re
p = 'web/core/includes/install.core.inc'
s = open(p).read()
old = """  arsort($required);
  arsort($non_required);

  $batch_builder = new BatchBuilder();"""
new = """  arsort($required);
  arsort($non_required);

  $debug_all = $required + $non_required;
  $debug_out = [];
  foreach (array_keys($debug_all) as $dm) { $debug_out[] = $dm . '(w' . $debug_all[$dm] . ')'; }
  file_put_contents("/tmp/batch_all.log", implode("\\n", $debug_out) . "\\n=== GROUPS ===\\n", FILE_APPEND);

  $batch_builder = new BatchBuilder();"""
assert old in s, "pattern1 not found"
s = s.replace(old, new)
old2 = '''  file_put_contents("/var/www/html/.batch_debug.log", json_encode($modules) . "\\n", FILE_APPEND);'''
new2 = '''  file_put_contents("/tmp/batch_groups.log", json_encode($modules) . "\\n", FILE_APPEND);'''
assert old2 in s, "pattern2 not found"
s = s.replace(old2, new2)
open(p,'w').write(s)
print("instrumented")
PYEOF
python3 /tmp/instrument.py 2>/dev/null || { echo "no python3, using sed/perl"; }
ls -la /tmp/batch_all.log /tmp/batch_groups.log 2>/dev/null
